import React,{useState} from "react";import "./App.css";import Header from "./components/Header";import TaskForm from "./components/TaskForm";import TaskList from "./components/TaskList";import useLocalStorage from "./hooks/useLocalStorage";import {initialTasks} from "./tasks";
function App(){const[tasks,setTasks]=useLocalStorage("tasks",initialTasks);const[filter,setFilter]=useState("all");const[search,setSearch]=useState("");const[darkMode,setDarkMode]=useState(false);const addTask=title=>setTasks([...tasks,{id:Date.now(),title,completed:false}]);const toggleTask=id=>setTasks(tasks.map(t=>t.id===id?{...t,completed:!t.completed}:t));const deleteTask=id=>setTasks(tasks.filter(t=>t.id!==id));const filtered=tasks.filter(t=>{const s=t.title.toLowerCase().includes(search.toLowerCase());if(filter==="completed")return t.completed&&s;if(filter==="pending")return !t.completed&&s;return s});const done=tasks.filter(t=>t.completed).length;return <div className={darkMode?"app dark":"app"}><div className="manager"><Header darkMode={darkMode} setDarkMode={setDarkMode}/><TaskForm addTask={addTask}/><div className="tools"><select value={filter} onChange={e=>setFilter(e.target.value)}><option value="all">Tất cả</option><option value="pending">Chưa làm</option><option value="completed">Hoàn thành</option></select><input placeholder="Tìm kiếm..........." value={search} onChange={e=>setSearch(e.target.value)}/></div><div className="stats">Tổng: {tasks.length} | Chưa làm: {tasks.length-done} | Hoàn thành: {done}</div><TaskList tasks={filtered} toggleTask={toggleTask} deleteTask={deleteTask}/></div></div>}
export default App;
